import org.junit.jupiter.api.io.TempDir;

/**
 * Storage-level guard for the language-tag variant merge: a losing value id is replaced in every position of a
 * statement quad - subject, predicate, object and context - in both the explicit and the inferred plane. RDF (and the
 * RDF4J API) only allows a literal as an object, so the other positions can only be reached with raw id quads; the
 * rewrite must not depend on the position.
 */
class LmdbLanguageTagVariantMergeStorageTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "http://example.org/";

	@TempDir
	File dataDir;

	private ValueStore valueStore;
	private TripleStore tripleStore;

	@AfterEach
	void tearDown() throws IOException {
		LmdbLanguageTagVariantMerge.statementBatchRowsForTesting = 0;
		close();
	}

	@Test
	void losingIdIsReplacedInEveryPositionOfBothPlanes() throws IOException {
		writeStoreProperties();
		open();
		long s = store(VF.createIRI(NS + "s"));
		long p = store(VF.createIRI(NS + "p"));
		long o = store(VF.createIRI(NS + "o"));
		long g = store(VF.createIRI(NS + "g"));
		long survivor = store(VF.createLiteral("abc", "en"));
		close();

		// cold value-id cache: the byte-exact legacy lookup hands the case variant a second id
		open();
		long loser = store(VF.createLiteral("abc", "EN"));
		assertNotEquals(survivor, loser, "fixture: two ids for one language literal");
		tripleStore.startTransaction();
		// explicit plane: the loser as subject, predicate, object and context, plus a row it collapses into
		tripleStore.storeTriple(loser, p, o, g, true);
		tripleStore.storeTriple(s, loser, o, g, true);
		tripleStore.storeTriple(s, p, loser, g, true);
		tripleStore.storeTriple(s, p, o, loser, true);
		tripleStore.storeTriple(s, p, survivor, g, true);
		tripleStore.storeTriple(s, p, loser, 0, true);
		// inferred plane: one row stays inferred, two become copies of explicit rows and must disappear
		tripleStore.storeTriple(loser, p, o, 0, false);
		tripleStore.storeTriple(s, p, loser, 0, false);
		tripleStore.storeTriple(s, p, o, loser, false);
		tripleStore.commit();

		LmdbLanguageTagVariantMerge.statementBatchRowsForTesting = 2;
		Outcome outcome = LmdbLanguageTagVariantMerge.mergeIfRequired(valueStore, tripleStore,
				new File(dataDir, "join-estimator.rjes").toPath());

		assertEquals(1, outcome.variantGroups());
		assertEquals(1, outcome.mergedValueIds());
		assertEquals(8L, outcome.rewrittenStatements());
		assertEquals(Set.of(
				quad(survivor, p, o, g),
				quad(s, survivor, o, g),
				quad(s, p, survivor, g),
				quad(s, p, o, survivor),
				quad(s, p, survivor, 0)), quads(true), "explicit statements after the merge");
		assertEquals(Set.of(quad(survivor, p, o, 0)), quads(false),
				"inferred statements after the merge; copies of explicit statements are dropped");
		assertEquals(Set.of(0L, g, survivor), contexts(), "the losing id is no longer a context");

		assertEquals(LanguageTagKeyMode.CANONICAL, valueStore.languageTagKeyMode());
		valueStore.clearCaches();
		assertEquals(survivor, valueStore.getId(VF.createLiteral("abc", "EN")));
		valueStore.clearCaches();
		assertNull(valueStore.getValue(loser), "the losing value is deleted");

		// the per-context statement counts are exact: a context disappears with its last statement, not before
		remove(survivor, p, o, g, true);
		remove(s, survivor, o, g, true);
		assertTrue(contexts().contains(g), "one statement is left in the context");
		remove(s, p, survivor, g, true);
		assertEquals(Set.of(0L, survivor), contexts());
		remove(s, p, survivor, 0, true);
		assertTrue(contexts().contains(0L), "the inferred statement is still in the default graph");
		remove(survivor, p, o, 0, false);
		remove(s, p, o, survivor, true);
		assertEquals(Set.of(), contexts());
	}

	@Test
	void mergeIsANoOpOnceTheStoreIsCanonical() throws IOException {
		writeStoreProperties();
		open();
		long s = store(VF.createIRI(NS + "s"));
		long p = store(VF.createIRI(NS + "p"));
		long survivor = store(VF.createLiteral("abc", "en"));
		close();
		open();
		long loser = store(VF.createLiteral("abc", "EN"));
		tripleStore.startTransaction();
		tripleStore.storeTriple(s, p, loser, 0, true);
		tripleStore.commit();

		Outcome first = LmdbLanguageTagVariantMerge.mergeIfRequired(valueStore, tripleStore,
				new File(dataDir, "join-estimator.rjes").toPath());
		assertEquals(1, first.mergedValueIds());
		Outcome second = LmdbLanguageTagVariantMerge.mergeIfRequired(valueStore, tripleStore,
				new File(dataDir, "join-estimator.rjes").toPath());
		assertEquals(0, second.mergedValueIds());
		assertEquals(0L, second.rewrittenStatements());
		assertEquals(Set.of(quad(s, p, survivor, 0)), quads(true));
	}

	private void open() throws IOException {
		StoreProperties properties = new StoreProperties(dataDir);
		assertTrue(properties.load(), "fixture: store.properties must exist");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		valueStore = new ValueStore(new File(dataDir, "values"), properties, config);
		tripleStore = new TripleStore(new File(dataDir, "triples"), properties, config, valueStore);
		properties.save();
	}

	private void close() throws IOException {
		if (tripleStore != null) {
			tripleStore.close();
			tripleStore = null;
		}
		if (valueStore != null) {
			valueStore.close();
			valueStore = null;
		}
	}

	private long store(Value value) throws IOException {
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(value);
		valueStore.commit();
		assertNotEquals(LmdbValue.UNKNOWN_ID, id);
		return id;
	}

	private void remove(long subj, long pred, long obj, long context, boolean explicit) throws IOException {
		int[] removed = new int[1];
		tripleStore.startTransaction();
		tripleStore.removeTriplesByContext(subj, pred, obj, context, explicit, quad -> removed[0]++);
		tripleStore.commit();
		assertEquals(1, removed[0], "exactly the one statement must be removed");
	}

	private Set<List<Long>> quads(boolean explicit) throws IOException {
		Set<List<Long>> quads = new HashSet<>();
		try (Txn txn = tripleStore.getTxnManager().createReadTxn();
				RecordIterator records = tripleStore.getTriples(txn, -1, -1, -1, -1, explicit)) {
			long[] quad;
			while ((quad = records.next()) != null) {
				assertTrue(quads.add(quad(quad[0], quad[1], quad[2], quad[3])), "no duplicate statement rows");
			}
		}
		return quads;
	}

	private Set<Long> contexts() throws IOException {
		Set<Long> contexts = new TreeSet<>();
		try (Txn txn = tripleStore.getTxnManager().createReadTxn();
				LmdbContextIdIterator iterator = tripleStore.getContexts(txn)) {
			long[] record;
			while ((record = iterator.next()) != null) {
				contexts.add(record[0]);
			}
		}
		return contexts;
	}

	private static List<Long> quad(long s, long p, long o, long c) {
		List<Long> quad = new ArrayList<>(4);
		quad.add(s);
		quad.add(p);
		quad.add(o);
		quad.add(c);
		return quad;
	}

	private void writeStoreProperties() throws IOException {
		Properties properties = new Properties();
		properties.setProperty(StoreProperties.VERSION_KEY, String.valueOf(LmdbStore.VERSION));
		properties.setProperty(StoreProperties.INDEXES_KEY, "spoc,posc");
		properties.setProperty(StoreProperties.TRIPLE_TERM_INDEXES_KEY, "spoc,cspo");
		properties.setProperty(StoreProperties.LANGUAGE_TAG_KEY, StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT);
		try (OutputStream out = new FileOutputStream(new File(dataDir, StoreProperties.FILE_NAME))) {
			properties.store(out, "test fixture");
		}
	}
}
